  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "In Sprague-Dawley rats, [11C]13 showed excellent brain permeability with a maximum SUV of 3.6 at 3 min in striatum, directly demonstrating meaningful CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "In wild-type mice, [11C]5i reached a whole-brain maximum uptake of 1.16 SUV, a moderate level of brain permeability (>1 SUV), supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In mice, [11C]QCA showed limited brain uptake with a peak of 0.42 %ID/g at 1 min, indicating poor penetration for the closest negative analog.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: multiple structurally related PET tracers show high or moderate brain uptake after systemic administration, including a close positive analog ([11C]13, SUVmax 3.6). The closest negative evidence (QCA) is a single compound with repeated poor-uptake records and is offset by the broader positive analog set; confidence is moderate because the closest evidence is mixed.",
  "evidence_gaps": [
    "Closest evidence is mixed: QCA (similarity 0.5) shows poor brain uptake, while [11C]13 (similarity 0.474) shows excellent uptake; no query-specific direct data are available.",
    "QCA negative records are repeated for the same compound and are not independent evidence of failure.",
    "No quantitative unbound brain/plasma or CSF data are provided; reliance is on PET/biodistribution uptake as a surrogate for meaningful CNS access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

